public enum EventOrchestratorV1CardDomainSource
{
    ExistingDeckOriginals = 1,
    GeneratedAtAdmission = 2,
}

public sealed class EventOrchestratorV1CardPolicyDefinition
{
    internal EventOrchestratorV1CardPolicyDefinition(
        EventOrchestratorV1ChildPolicyKind policyKind,
        string policyId,
        string parentStableId,
        CardSelectionV1Operation operation,
        int minSelect,
        int maxSelect,
        CardSelectionV1CommitMode commitMode,
        EventOrchestratorV1CardDomainSource domainSource,
        int minimumDomainCount,
        int maximumDomainCount)
    {
        if (policyKind is not (EventOrchestratorV1ChildPolicyKind.CheeseGorgeAddTwo or
                EventOrchestratorV1ChildPolicyKind.EventCardSelection) ||
            !IsPolicyId(policyId) || !RoomFlowIdentity.IsEventStableId(parentStableId) ||
            !Enum.IsDefined(operation) || !Enum.IsDefined(commitMode) ||
            !Enum.IsDefined(domainSource) ||
            minSelect is < 1 or > CardSelectionV1Limits.MaximumSelectedCards ||
            maxSelect is < 1 or > CardSelectionV1Limits.MaximumSelectedCards ||
            minSelect > maxSelect ||
            minimumDomainCount is < 1 or > EventOrchestratorV1Limits.MaximumChildDomainCount ||
            maximumDomainCount is < 1 or > EventOrchestratorV1Limits.MaximumChildDomainCount ||
            minimumDomainCount > maximumDomainCount || minimumDomainCount < maxSelect ||
            (operation == CardSelectionV1Operation.Add) !=
                (domainSource == EventOrchestratorV1CardDomainSource.GeneratedAtAdmission))
            throw new ArgumentException("The event card policy definition is invalid.");
        PolicyKind = policyKind;
        PolicyId = policyId;
        ParentStableId = parentStableId;
        Operation = operation;
        MinSelect = minSelect;
        MaxSelect = maxSelect;
        CommitMode = commitMode;
        DomainSource = domainSource;
        MinimumDomainCount = minimumDomainCount;
        MaximumDomainCount = maximumDomainCount;
    }

    public EventOrchestratorV1ChildPolicyKind PolicyKind { get; }
    public string PolicyId { get; }
    public string ParentStableId { get; }
    public CardSelectionV1Operation Operation { get; }
    public int MinSelect { get; }
    public int MaxSelect { get; }
    public CardSelectionV1CommitMode CommitMode { get; }
    public EventOrchestratorV1CardDomainSource DomainSource { get; }
    public int MinimumDomainCount { get; }
    public int MaximumDomainCount { get; }

    public EventOrchestratorV1ChildPolicy Bind(int expectedDomainCount)
    {
        if (expectedDomainCount < MinimumDomainCount ||
            expectedDomainCount > MaximumDomainCount)
            throw new ArgumentOutOfRangeException(nameof(expectedDomainCount));
        return new EventOrchestratorV1ChildPolicy(this, expectedDomainCount);
    }

#if EVENT_CARD_OPERATIONS_TEST_SEAM
    public static EventOrchestratorV1CardPolicyDefinition CreateForTests(
        string policyId,
        string parentStableId,
        CardSelectionV1Operation operation,
        int minSelect,
        int maxSelect,
        CardSelectionV1CommitMode commitMode,
        EventOrchestratorV1CardDomainSource domainSource,
        int minimumDomainCount,
        int maximumDomainCount) =>
        new(EventOrchestratorV1ChildPolicyKind.EventCardSelection,
            policyId, parentStableId, operation, minSelect, maxSelect, commitMode,
            domainSource, minimumDomainCount, maximumDomainCount);
#endif

    private static bool IsPolicyId(string? value)
    {
        if (value is null || value.Length is < 1 or > 64 ||
            value is EventOrchestratorV1Limits.ItemRewardPolicy or
                EventOrchestratorV1Limits.UnsupportedCardPolicy)
            return false;
        foreach (char c in value)
            if (!(c is >= 'a' and <= 'z' or >= '0' and <= '9' or '_')) return false;
        return true;
    }
}

