{
    PolicyKind = EventOrchestratorV1ChildPolicyKind.ItemReward;
    ChildKind = EventOrchestratorV1ChildKind.Item;
    PolicyId = EventOrchestratorV1Limits.ItemRewardPolicy;
    ParentStableId = string.Empty;
}

