public static EventOrchestratorV1ChildPolicy CheeseGorgeAddTwo()
{
    if (!EventOrchestratorV1CardPolicyCatalog.TryGet(
            EventOrchestratorV1Limits.CheeseGorgeAddTwoPolicy,
            out EventOrchestratorV1CardPolicyDefinition? definition) || definition is null)
        throw new InvalidOperationException("The Cheese policy is unavailable.");
    return definition.Bind(8);
